			state: BuildTaskState;
			/** 任务当前的进度（通常为 0.0 ~ 1.0） */
			progress: number;
			/** 进度 / 状态文案:processing 时为当前阶段进度,失败时为具体错误原因(含 stage 失败的报错) */
			message?: string;
			/** 失败原因(与失败态的 message 同源);非失败态为 undefined */
			error?: string;
			/** 任务创建时间戳(ms),host 在创建/重启任务时设置 */
			createdAt?: number;
			/** 本轮执行开始时间，用于识别同一任务的重新执行 */
			startedAt?: number;
			/** 唯一的构建批次标识；同一次用户发起的构建共享该值。旧任务没有此字段。 */
			groupId?: string;
			/** 构建批次创建时间戳(ms)，用于批次展示；与任务自身 createdAt 分离。 */
			groupCreatedAt?: number;
			/** 任务完成时间戳(ms),host 在 success/failure/cancelled/generated 终态时设置 */
			completedAt?: number;
			/** 成功构建的最终结果，包含平台提供的 custom 数据（如 web-mobile 的 previewUrl）。 */
			result?: IBuildResultData;
			/** 已请求取消；运行中的任务仍需等待底层收尾才进入 cancelled */
			cancelRequested?: boolean;
			/** 当前轮次已执行阶段的结果，按执行顺序排列 */
			stageResults?: IBuildStageResult[];
			/** 任务的 build options 快照。所有 UI 需要的衍生信息都从这里读,不在 IBuildTask 上自创字段:
			 *  - 输出目录:`path.join(options.buildPath, options.outputName)`
			 *  - 日志路径:`options.logDest`
			 *  - 阶段链:`options.buildStageGroup` */
			options?: IBuildOptions;
			/** 父任务 ID（仅子任务携带，用于级联操作和 UI 过滤） */
			parentTaskId?: string;
			/** 子任务 ID 列表（仅父任务携带，按创建顺序排列） */
			childTaskIds?: string[];
		}

