export interface ILocalConfig {
			/** API 地址覆盖 */
			api?: {
				gate?: string;
				api?: string;
				auth?: string;
				telemetry?: string;
				/** Pink 产品埋点配置查询接口地址 */
				productTelemetryConfig?: string;
				/** 用户中心地址 */
				userCenter?: string;
			};
			/** 功能开关 */
			feature?: {
				/** 激活码校验开关。缺省为 `false`，仅布尔 `true` 时开启。 */
				activation_code?: boolean;
				/** Agent 兑换码开关。缺省为 `false`。 */
				agent_redeem_code?: boolean;
				/** 是否启用 PinK 模块 */
				pinkModule: boolean;
				/** 常驻显示 Test Helper 入口 */
				testHelper: boolean;
				/** 是否启用动画编辑器 */
				animationEditor: boolean;
				/** 是否启用加密（预留开关） */
				encryption?: boolean;
				/** 默认 true：产品埋点全部上报；false：遵守现有 TelemetryLevel 和产品遥测限制。重启后生效。 */
				productTelemetryAlwaysReport?: boolean;
				/** 是否启用 cocos-cli 运行时模块缓存（Cocos Host 进程的 Module.load 缓存钩子）。缺省为 `false`（关闭）。 */
				runtimeModuleCache?: boolean;
			};
			/** 运行环境 */
			env?: 'dev' | 'fat' | 'prod';
			/** 构建容器嵌入页面(首页 + 文档面板)。有 url 即启用 iframe 加载;zipUrl 共用一个 zip(约定入口 home/、doc/)。
			 *  source 选择来源:缺省 auto(在线 url > ota > bundled > internal),其余取值锁定单一来源。 */
			builderEmbedding?: {
				/** 嵌入页来源。缺省 = `'auto'`(走整条链路);其余取值锁定单一来源,见 {@link BuilderEmbeddingSource} */
				source?: BuilderEmbeddingSource;
				home?: { url?: string };
				doc?: { url?: string };
				zipUrl?: string;
			};
			/**
			 * 构建面板平台目录本地覆盖(可见性 + 分组 + 排序)。优先级最高:本地 > 服务端下发 > 本地兜底。
			 * 便于本地调试平台显隐 / 分组 / 排序,直接写在 `~/.pink/api-config.json`,无需依赖服务端下发。
			 *
			 * **仅 `builderEmbedding.source === 'internal'` 时生效**:它是「脱离线上配置的本地测试通道」——新平台
			 * 自测阶段用它把尚未在服务端上架的平台显示出来,测完再上架。其余来源下目录由热更插件包元数据决定。
			 */
			builderPlatforms?: IBuilderPlatformCatalogItem[];
			/** 构建面板分类容器目录本地覆盖(每项一个侧边 tab)。优先级最高:本地 > 服务端下发 > 内置兜底。
			 *  与 {@link builderPlatforms} 同样**仅 `builderEmbedding.source === 'internal'` 时生效**。 */
			builderCategories?: IBuilderCategory[];
		}

