			 * 仅支持 Scene Runtime。图片库、图片参数和可见性在项目内共享，绑定按场景保存
			 * 配置修改立即持久化，不进入 Scene Undo，也不依赖场景保存
			 */
			'reference-image': {
				/** 查询图片库、当前场景绑定和实际显示状态 */
				'query': InvokeCommand<void, _cli.IReferenceImageState>;
				/** 将本地 PNG/JPG/JPEG 图片加入图片库并绑定到当前场景，path 为绝对路径 */
				'add-and-select': InvokeCommand<{ path: string }, _cli.IReferenceImageState>;
				/** 从图片库移除图片并清除相关场景绑定，保留原始文件 */
				'remove': InvokeCommand<{ path: string }, _cli.IReferenceImageState>;
				/** 将图片库中的图片绑定到当前场景 */
				'select': InvokeCommand<{ path: string }, _cli.IReferenceImageState>;
				/** 清除当前场景的参考图绑定 */
				'clear-binding': InvokeCommand<void, _cli.IReferenceImageState>;
				/** 设置项目共享的显示开关，实际显示状态仍取决于视图模式和图片加载结果 */
				'set-visible': InvokeCommand<{ visible: boolean }, _cli.IReferenceImageState>;
				/**
