				>;
			};
			/**
			 * 查询和控制编辑模式下的 cc.ParticleSystem
			 *
			 * 仅支持 Scene Runtime。播放操作沿用 CLI 当前选中组及其粒子父子层级，不改变选择
			 * void 表示调用完成，不包含实际受影响的组件列表
			 */
			particle: {
				/**
				 * 查询指定组件的粒子运行状态
