				 * uuid 为组件 UUID；沿用 CLI 直接赋值行为，不创建 Undo 记录，也不保存场景
				 * 需要 Undo 时应使用 component.set-property 写入 simulationSpeed
				 */
				'set-play-speed': InvokeCommand<{ uuid: string; speed: number }, void>;
				/** 播放当前选中组的粒子 */
