				'query-state': InvokeCommand<void, _cli.IAnimationStateInfo>;
				'query-session': InvokeCommand<void, IAnimationSessionSnapshot>;
				'execute-guarded': InvokeCommand<IAnimationGuardedRequest, IAnimationGuardedResult>;
				'query-root': InvokeCommand<_cli.IAnimationTargetOptions, _cli.IAnimationRootResult>;
				'query-root-info': InvokeCommand<_cli.IAnimationTargetOptions, _cli.IAnimationRootInfo>;
				'query-clip': InvokeCommand<_cli.IAnimationQueryClipOptions, _cli.IAnimationClipDump>;
				'query-clips': InvokeCommand<_cli.IAnimationTargetOptions, _cli.IAnimationClipsInfo>;
				'query-properties': InvokeCommand<_cli.IAnimationTargetOptions, _cli.IAnimationPropertyInfo[]>;
				'query-time': InvokeCommand<_cli.IAnimationTimeOptions | undefined, number>;
				'query-property-value-at-frame': InvokeCommand<_cli.IAnimationQueryPropertyValueAtFrameOptions, _cli.IAnimationValue>;
				'query-auxiliary-curve-value-at-frame': InvokeCommand<_cli.IAnimationQueryAuxiliaryCurveValueAtFrameOptions, _cli.IAnimationKeyValueDump | null>;
				'set-time': InvokeCommand<_cli.IAnimationSetTimeOptions, boolean>;
				'change-play-state': InvokeCommand<_cli.IAnimationPlayStateOptions, boolean>;
				'change-edit-clip': InvokeCommand<_cli.IAnimationEditClipOptions, boolean>;
				'apply-operations': InvokeCommand<_cli.IAnimationOperationOptions, _cli.IAnimationOperationResult>;
				'save': InvokeCommand<IAnimationSaveOptions | undefined, boolean>;
			};
			preview: {
				'show-motion': InvokeCommand<_cli.MotionPreviewDesc, boolean>;
				'hide-motion': InvokeCommand<void, void>;
				'set-motion-model': InvokeCommand<string, void>;
				'set-motion-time': InvokeCommand<number, void>;
				'play-motion': InvokeCommand<void, void>;
				'pause-motion': InvokeCommand<void, void>;
				'stop-motion': InvokeCommand<void, void>;
				'set-motion-variable': InvokeCommand<{ name: string; value: number }, void>;
				'set-motion-parameter': InvokeCommand<{ axis: 'value' | 'x' | 'y'; value: number }, void>;
				'get-motion-timeline-stats': InvokeCommand<void, { timeLineLength: number } | null>;
				'is-motion-active': InvokeCommand<void, boolean>;
				'query-motion-image': InvokeCommand<{ width: number; height: number }, unknown>;
				'on-motion-mouse-down': InvokeCommand<{ x: number; y: number; button: number }, void>;
				'on-motion-mouse-move': InvokeCommand<{ movementX: number; movementY: number }, void>;
				'on-motion-mouse-up': InvokeCommand<{ x: number; y: number }, void>;
				'on-motion-mouse-wheel': InvokeCommand<{ wheelDeltaY: number; wheelDeltaX: number }, void>;
			};
			asset: {
				'asset-changed': InvokeCommand<string, void>;
			};
			script: {
				'investigate-packer-driver': InvokeCommand<void, void>;
			};
			undo: {
				'undo': InvokeCommand<_cli.IUndoOperationOptions | undefined, IUndoRedoResult>;
				'can-undo': InvokeCommand<_cli.IUndoOperationOptions | undefined, boolean>;
				'is-dirty': InvokeCommand<void, boolean>;
				'mark-saved': InvokeCommand<void, void>;
				'clear-history': InvokeCommand<void, void>;
				'begin-recording': InvokeCommand<IUndoRecordingParams, string>;
