			};
			redo: {
				'redo': InvokeCommand<_cli.IUndoOperationOptions | undefined, IUndoRedoResult>;
				'can-redo': InvokeCommand<_cli.IUndoOperationOptions | undefined, boolean>;
			};
			material: {
				'query-material': InvokeCommand<string, unknown>;
				'apply-material': InvokeCommand<{ uuid: string; material: unknown }, boolean>;
				'preview-material': InvokeCommand<{ uuid: string; material?: unknown; emit?: boolean }, boolean>;
				'query-all-effects': InvokeCommand<void, unknown>;
				'query-effect': InvokeCommand<string, unknown>;
			};
			prefab: {
				'unlink': InvokeCommand<IUnlinkPrefabParams, boolean>;
				'unpack': InvokeCommand<IUnpackPrefabInstanceParams, INode>;
				'is-instance': InvokeCommand<IIsPrefabInstanceParams, boolean>;
				'revert': InvokeCommand<IRevertToPrefabParams, boolean>;
				'apply-changes': InvokeCommand<IApplyPrefabChangesParams, boolean>;
				'create-prefab': InvokeCommand<ICreatePrefabFromNodeParams, INode>;
