		}

scene.InvokeParamIsVoid.declaration:
export type InvokeParamIsVoid<P> =
			[P] extends [void]
			? keyof P extends never ? true : false
			: false;

scene.SceneInvokeOptions.declaration:
export interface SceneInvokeOptions {
			/** 等待响应的毫秒数，范围 (0, 2147483647]；省略时使用默认值，超时不代表业务被取消。 */
			readonly timeoutMs?: number;
		}

scene.InvokeArgs.declaration:
export type InvokeArgs<T extends InvokeTarget, M extends InvokeMethod<T>> =
			InvokeParamIsVoid<InvokeParams<T, M>> extends true
			? [params?: undefined, options?: SceneInvokeOptions]
			: undefined extends InvokeParams<T, M>
			? [params?: Exclude<InvokeParams<T, M>, undefined>, options?: SceneInvokeOptions]
			: [params: InvokeParams<T, M>, options?: SceneInvokeOptions];

scene.InvokeWithParams.declaration:
export type InvokeWithParams<T extends InvokeTarget> = {
			[M in InvokeMethod<T>]: InvokeParamIsVoid<InvokeParams<T, M>> extends true ? never : M
		}[InvokeMethod<T>];

scene.InvokeNoParams.declaration:
export type InvokeNoParams<T extends InvokeTarget> = {
			[M in InvokeMethod<T>]: InvokeParamIsVoid<InvokeParams<T, M>> extends true ? M : undefined extends InvokeParams<T, M> ? M : never
		}[InvokeMethod<T>];

scene.InvokeParam.declaration:
export type InvokeParam<T extends InvokeTarget, M extends InvokeWithParams<T>> =
			undefined extends InvokeParams<T, M>
			? Exclude<InvokeParams<T, M>, undefined> | undefined
			: InvokeParams<T, M>;

scene.IPropertyChangeEvent.declaration:
export interface IPropertyChangeEvent {
			/** 局部刷新：合并提供的顶层字段，属性子树整体替换；不清除省略字段。场景设置不携带光照探针烘焙数据。 */
			partial?: boolean;
			/** 变更目标类型。 */
			target: IPropertyChangeTarget;
			/** 目标路径；节点属性为节点路径，场景根为 `/`。 */
			path: string;
			/** 发生变化的属性路径，如 `position`、`locked`、`__comps__.0.enabled`。 */
			propPath?: string;
			/** 变化来源，由场景进程上报，如 `editor`、`engine`、`undo`。 */
			source?: string;
			/** 变更后的 dump；partial 为 true 时只合并提供的顶层字段，不清除省略字段。 */
			dump: INode | IScene;
		}

scene.INodeChangeEvent.declaration:
export interface INodeChangeEvent {
			/** 局部节点数据，消费方式与 IPropertyChangeEvent.partial 相同。 */
			partial?: boolean;
			/** 变更后的节点或场景根 dump。 */
			node: INode | IScene;
			/**
			 * 节点变化类型。
			 * - `state`：节点自身状态变化，如名称、激活、锁定、预制体状态或组件摘要变化，适合更新 Hierarchy 单个节点展示。
			 * - `structure`：层级结构变化，如父子关系、children 顺序或路径变化，适合刷新或移动 Hierarchy 子树。
			 * - `unknown`：底层场景进程没有提供足够信息，消费者应保守刷新相关视图。
			 */
			changeType: INodeChangeType;
			/** 发生变化的属性路径（如果场景进程提供或可由内部前后快照推断）。 */
			propPath?: string;
			/** 变化来源，由场景进程上报，如 `editor`、`engine`、`undo`。 */
			source?: string;
			/** 路径发生变化时的旧路径，主要用于 rename/move 的增量更新。 */
			previousPath?: string;
		}

