scene.ISceneChangeEvent.declaration:
export type ISceneChangeEvent =
			| { kind: 'node-created'; node: INode }
			| { kind: 'node-deleted'; node: INode }
			| { kind: 'property-changed'; change: IPropertyChangeEvent }
			| { kind: 'node-changed'; event: INodeChangeEvent }
			| { kind: 'component-added'; component: IComponent }
			| { kind: 'component-removed'; component: IComponent }
			/** 粒子包围盒临时显隐通知，不产生属性修改或 Undo。 */
			| { kind: 'particle-bounds-visibility-changed'; componentUuid: string; visible: boolean }
			| { kind: 'dirty-changed'; dirty: boolean }
			/** 当前场景的反射探针任务状态变化。 */
			| { kind: 'reflection-probe-task-changed'; state: _cli.IReflectionProbeTaskState }
			| { kind: 'animation-state-changed'; event: IAnimationStateChangedEvent }
			| { kind: 'animation-time-changed'; event: IAnimationTimeChangedEvent }
			| { kind: 'animation-clip-changed'; event: IAnimationClipEvent }
			| { kind: 'animation-property-committed'; change: IPropertyChangeEvent }
			/**
			 * 同一 Runtime 内的场景内容整体替换：运行脚本切场景（Preview 内 `director.loadScene()`）
			 * 只广播 `editor:close` / `editor:open`，新场景已有节点仅初始化、不再补发增量结构事件，
			 * 因此消费方需要按内容重载处理，不能指望 node-created / node-deleted 补齐。
			 */
			| { kind: 'scene-content-replaced' };

scene.IUndoRedoResult.declaration:
export interface IUndoRedoResult {
