			/** CLI 记录的命令 ID，例如 `node:create`、`component:set-property`。 */
			commandId?: string;
			/** CLI 记录的命令显示名。 */
			label?: string;
			/** 失败原因，例如 `Cannot undo` 或 `Cannot redo`。 */
			reason?: string;
		}

