scene.SceneInstance.declaration:
export interface SceneInstance {
			/** 此实例绑定的精确 Runtime 引用。 */
			readonly runtimeRef: SceneRuntimeRef;
			/** 场景资源 UUID */
			readonly uuid: string;
			/** 场景资源 URL，如 `db://assets/main.scene` */
			readonly url: string;
			/** 场景文件路径 */
			readonly file: string;
			/** 是否通过编辑器打开（`false` 表示后台加载） */
			readonly openEditor: boolean;

			/**
			 * 返回场景实例的引用数据。
			 */
			toRef(): ISceneRef;

			// ── 场景控制 ──

			/**
			 * 关闭该场景。
			 * @see {@link onDidClose} 场景关闭后触发
			 */
			close(): Thenable<void>;

			/**
			 * 保存该场景。
			 * @see {@link onDidSave} 场景保存后触发
			 */
			save(): Thenable<void>;

			/**
			 * 原位重载场景或 Prefab 并清理 Undo 历史，不自动保存
			 *
			 * 仅完成时返回，失败或入队状态抛出错误；运行预览不支持此操作
			 * @see onDidReload 重载后应重新获取任务绑定
			 */
			reload(): Thenable<void>;

			/**
			 * 撤销最近一次场景历史操作。
			 */
			undo(): Thenable<IUndoRedoResult>;

			/**
			 * 重做最近一次被撤销的场景历史操作。
			 */
			redo(): Thenable<IUndoRedoResult>;

			/**
			 * 调用场景实例 API。第一个参数选择 API 分组，第二个参数选择该分组下的命令，
			 * 第三个参数由前两个参数共同决定；无参数命令不需要传第三个参数。
			 *
			 * 新增可调用 API 时必须先加入 {@link InvokeAPIMap}。
			 *
			 * @example
			 * ```ts
			 * await scene.invoke('node', 'set-property', {
			 *   nodePath: 'Canvas/Button',
			 *   path: 'active',
			 *   dump: { value: true },
			 * });
			 * await scene.invoke('component', 'set-property', {
			 *   nodePath: 'Canvas/Button',
			 *   path: '__comps__.0.interactable',
			 *   dump: { value: false },
			 * });
			 * // 通信选项固定放在业务参数之后；无参数命令使用 undefined 占位。
			 * await scene.invoke('undo', 'is-dirty', undefined, { timeoutMs: 5000 });
			 * ```
			 */
			invoke<T extends InvokeTarget, M extends InvokeMethod<T>>(
				target: T,
				method: M,
				...args: InvokeArgs<T, M>
			): Thenable<InvokeResult<T, M>>;
			invoke<T extends InvokeTarget, M extends InvokeWithParams<T>>(
				target: T,
				method: M,
				params: InvokeParam<T, M>,
				options?: SceneInvokeOptions,
			): Thenable<InvokeResult<T, M>>;
			invoke<T extends InvokeTarget, M extends InvokeNoParams<T>>(
				target: T,
				method: M,
			): Thenable<InvokeResult<T, M>>;

			// ── 节点查询 ──

			/**
			 * 查询节点树（层级管理器格式）。返回递归树结构，包含节点名称、激活状态、组件信息、预制体状态等。
			 *
			 * @param params 可选，查询节点树参数
			 * @returns 节点树根项；场景未打开时返回 `null`
			 *
			 * @example
			 * ```ts
			 * const tree = await scene.queryNodeTree();
			 * const subTree = await scene.queryNodeTree({ path: 'Canvas/Player' });
			 * ```
			 */
			queryNodeTree(params?: IQueryNodeTreeParams): Thenable<INodeTreeItem | null>;

			/**
			 * 查询已注册类；可按父类筛选，用于识别可以赋值给指定类型的子类。
			 *
			 * @param options 可选的继承关系过滤条件
			 * @returns 匹配的类名列表
			 */
			queryClasses(options?: IQueryClassesOptions): Thenable<Array<{ name: string }>>;

			/**
			 * 查询节点或组件的详细信息。
			 * 优先通过 `kind` 指定查询目标类型：
			 * - `kind: 'node'`：按节点路径查询
			 * - `kind: 'component'`：按组件路径查询
			 * - 未指定或 `kind: 'auto'`：先查询节点，节点不存在时再查询组件
			 * - 传入路径数组时批量查询，返回等长数组
			 *
			 * @param params 查询参数
			 * @returns 节点或组件详情；不存在时返回 `null`
			 *
			 * @example
			 * ```ts
			 * const node = await scene.query({ path: 'Canvas/Player', kind: 'node' });
			 * const component = await scene.query({ path: 'Canvas/Player/cc.Sprite', kind: 'component' });
			 * const dumps = await scene.query({ path: ['Canvas/Player', 'Canvas/Enemy'] });
			 * ```
			 */
			query(params: Omit<IQueryParams, 'path'> & { path: string }): Thenable<IScene | INode | IComponent | null>;
			query(params: Omit<IQueryParams, 'path'> & { path: string[] }): Thenable<(IScene | INode | IComponent | null)[]>;
			query(params: IQueryParams): Thenable<IScene | INode | IComponent | null | (IScene | INode | IComponent | null)[]>;

			// ── 节点操作 ──

			/**
			 * 在场景中按类型创建节点。
			 *
			 * @param params 创建节点参数
			 * @returns 新建节点信息
			 * @see {@link onDidCreateNode} 节点创建后触发
			 *
			 * @example
			 * ```ts
			 * const node = await scene.createNodeByType({ nodeType: 'Empty' });
			 * const child = await scene.createNodeByType({ nodeType: 'Sprite', path: 'Canvas', name: 'MySprite' });
			 * ```
			 */
			createNodeByType(params: ICreateNodeParams): Thenable<INode>;
			/**
			 * 批量创建节点（流式）。逐个执行并 yield 每个新建节点。
			 *
			 * @example
			 * ```ts
			 * for await (const node of scene.createNodeByType([
			 *   { nodeType: 'Empty', name: 'A' },
			 *   { nodeType: 'Sprite', name: 'B', path: 'Canvas' },
			 * ])) {
			 *   console.log('created:', node.name);
			 * }
			 * ```
			 */
			createNodeByType(params: ICreateNodeParams[]): AsyncIterable<INode>;

			/**
			 * 在场景中按资产创建节点。
			 *
			 * @param params 创建节点参数
			 * @returns 新建节点信息
			 * @see {@link onDidCreateNode} 节点创建后触发
			 *
			 * @example
			 * ```ts
			 * const node = await scene.createNodeByAsset({ dbURL: 'db://assets/prefab.prefab' });
			 * ```
			 */
			createNodeByAsset(params: ICreateNodeByAssetParams): Thenable<INode>;
			/**
			 * 批量按资产创建节点（流式）。逐个执行并 yield 每个新建节点。
			 */
			createNodeByAsset(params: ICreateNodeByAssetParams[]): AsyncIterable<INode>;

			/**
			 * 删除场景中的指定节点。
			 *
			 * @param params 删除节点参数
			 * @returns 写操作，无返回值；非存在路径静默成功（幂等）
			 * @see {@link onDidDeleteNode} 节点删除后触发
			 *
			 * @example
			 * ```ts
			 * await scene.deleteNode({ path: 'Canvas/MySprite' });
			 * ```
			 */
			deleteNode(params: IDeleteNodeParams): Thenable<void>;
			/**
			 * 批量删除节点（流式）。逐个执行并 yield；非存在路径静默成功。
			 */
			deleteNode(params: IDeleteNodeParams[]): AsyncIterable<void>;

			/**
			 * 设置节点或组件的属性。
			 *
			 * 使用 `nodePath` 定位节点，`path` 指定属性路径：
			 * - 节点属性：`path` 为属性名（如 `'position'`、`'active'`、`'name'`）
			 * - 组件属性：`path` 为 `__comps__.<index>.<propName>`
			 *
			 * @see {@link query} 查询节点/组件 dump 数据
			 * @see {@link onDidChangeProperty} 属性更新后触发
			 *
			 * @example
			 * ```ts
			 * await scene.setProperty({
			 *   nodePath: 'Canvas/MySprite',
			 *   path: 'position',
			 *   dump: { value: { x: 100, y: 200, z: 0 }, type: 'cc.Vec3' },
			 * });
			 * await scene.setProperty({
			 *   nodePath: 'Canvas/MyNode',
			 *   path: '__comps__.0.string',
			 *   dump: { value: 'Hello', type: 'String' },
			 * });
			 * ```
			 */
			setProperty(params: ISetPropertyParams): Thenable<void>;
			/**
			 * 批量设置属性（流式）。
			 */
			setProperty(params: ISetPropertyParams[]): AsyncIterable<void>;

			// ── 组件操作 ──

			/**
			 * 在指定节点上添加组件。
			 *
			 * @param params 添加组件参数
			 * @returns 新添加的组件信息
			 * @see {@link onDidAddComponent} 组件添加后触发
			 *
			 * @example
			 * ```ts
			 * const comp = await scene.addComponent({ nodePath: 'Canvas/MyNode', component: 'cc.Sprite' });
			 * ```
			 */
			addComponent(params: IAddComponentParams): Thenable<IComponent>;

			/**
			 * 移除指定组件。
			 *
			 * @param params 移除组件参数
			 * @returns 成功移除返回被移除组件的 dump 数据；组件不存在返回 `null`
			 * @see {@link onDidRemoveComponent} 组件移除后触发
			 *
			 * @example
			 * ```ts
			 * await scene.removeComponent({ path: 'Canvas/MyNode/cc.Sprite' });
			 * ```
			 */
			removeComponent(params: IRemoveComponentParams): Thenable<IComponent | null>;

			// ── 选择 ──

			/**
			 * 选择场景中的元素。
			 *
			 * @param params 选择参数
			 * @see {@link onDidSelectNode} 节点被选中后触发
			 *
			 * @example
			 * ```ts
			 * await scene.select({ path: 'Canvas/MyNode' });
			 * await scene.select({ path: ['Canvas/A', 'Canvas/B'] });
			 * ```
			 */
			select(params: ISelectParams): Thenable<void>;

			/**
			 * 取消选择场景中的指定元素。
			 *
			 * @param params 取消选择参数
			 * @see {@link onDidDeselectNode} 节点被取消选择后触发
			 */
			deselect(params: IDeselectParams): Thenable<void>;

			/**
			 * 清空场景中的所有选择。
			 * @see {@link onDidClearSelection} 选择被清空后触发
			 */
			deselectAll(): Thenable<void>;

			/**
			 * 获取当前选中的节点路径列表。完整选择快照以本方法为准；
			 * {@link onDidSelectNode}/{@link onDidDeselectNode} 只表示单次增量变化。
			 *
			 * @returns 当前选中节点的路径数组；无选中时返回空数组
			 * @see {@link select} 选择节点
			 */
			getSelection(): Thenable<string[]>;

			// ── 摄像机 ──

			/**
			 * 将编辑器摄像机聚焦到指定节点；不传参数时聚焦当前选中的节点。
			 *
			 * @param params 聚焦参数
			 *
			 * @example
			 * ```ts
			 * await scene.focus();
			 * await scene.focus({ path: 'Canvas/MyNode' });
			 * await scene.focus({ path: ['Canvas/A', 'Canvas/B'] });
			 * ```
			 */
			focus(params?: IFocusParams): Thenable<void>;

			// ── 节点操作（语义封装） ──

			/**
			 * 将指定节点复制到场景剪贴板。
			 *
			 * 这是节点语义 API，内部等价于 `invoke('node', 'copy', { paths })`。
			 * 其他剪贴板细分能力（paste/duplicate/cut/queryClipboardState）请直接使用 {@link invoke}。
			 *
			 * @example
			 * ```ts
			 * const copied = await scene.copyNode({ path: 'Canvas/MyNode' });
			 * ```
			 */
			copyNode(params: ICopyNodeParams): Thenable<string[]>;

			/**
			 * 将节点移动到新的父节点下。
			 *
			 * 这是节点语义 API，内部先调用 `invoke('node', 'set-parent', ...)`。
			 * 如需精确调整兄弟顺序，可在移动后继续调用 `invoke('node', 'reorder', ...)`。
			 *
			 * @example
			 * ```ts
			 * const moved = await scene.moveNode({ path: 'Canvas/A', parentPath: 'Canvas/B' });
			 * ```
			 */
			moveNode(params: IMoveNodeParams): Thenable<string[]>;

			// ── 实例事件（仅触发属于该场景的事件） ──

			/**
			 * 节点创建后触发。
			 *
			 * @example
			 * ```ts
			 * scene.onDidCreateNode(node => {
			 *   console.log(`新节点: ${node.name}`);
			 * });
			 * ```
			 */
			readonly onDidCreateNode: Event<INode>;

			/** 节点删除后触发。 */
			readonly onDidDeleteNode: Event<INode>;

			/**
			 * 场景内容变化后触发。
			 *
			 * 该事件是节点、组件和属性变化的统一入口；如果只关心某类变化，
			 * 可以继续使用下面的细分事件。
			 *
			 * 推荐优先按 `kind` 分支消费，避免把不同来源的变化当成重复事件。
			 *
			 * @example
			 * ```ts
			 * scene.onDidChange(event => {
			 *   switch (event.kind) {
			 *     case 'property-changed':
			 *       console.log(`属性变化: ${event.change.propPath}`);
			 *       break;
			 *     case 'node-changed':
			 *       console.log(`节点变化: ${event.event.changeType}`);
			 *       break;
			 *     case 'component-added':
			 *     case 'component-removed':
			 *       console.log(`组件变化: ${event.component.type}`);
			 *       break;
			 *   }
			 * });
			 * ```
			 */
			readonly onDidChange: Event<ISceneChangeEvent>;

			/**
			 * 节点或组件属性变更后触发。
			 *
			 * 该事件来自场景 webview 的实时 `node:change` 广播，而不是 API 调用回响；
			 * 因此通过 {@link setProperty}、Gizmo、撤销/重做或引擎内部操作修改可检查属性时都会触发。
			 *
			 * 仅在场景进程提供属性路径，或 PinK 可从内部前后快照推断出属性路径时触发。
			 * 结构变化（父子关系、children 顺序）不触发本事件，请监听 {@link onDidChangeNode}。
			 */
			readonly onDidChangeProperty: Event<IPropertyChangeEvent>;

			/**
			 * 节点状态或层级结构变化时触发（包含场景根节点）。
			 *
			 * 覆盖**所有节点变化来源**——主动 API 调用、Gizmo、脚本、撤销/重做、其他面板修改等。
			 * `changeType: 'state'` 表示名称、激活、锁定、预制体或组件摘要变化，适合更新树节点展示；
			 * `changeType: 'structure'` 表示父子关系或排序变化，适合 Hierarchy 重新加载局部树；
			 * `changeType: 'unknown'` 表示底层场景进程没有提供足够信息，扩展应保守刷新相关视图。
			 *
			 * 纯 transform/size/anchor 等高频属性变化只触发 {@link onDidChangeProperty}，
			 * 不触发本事件，避免 Hierarchy 被无意义刷新。
			 */
			readonly onDidChangeNode: Event<INodeChangeEvent>;

			/** 组件添加后触发。 */
			readonly onDidAddComponent: Event<IComponent>;

			/** 组件移除后触发。 */
			readonly onDidRemoveComponent: Event<IComponent>;

			/**
			 * 节点被选中时触发。
			 *
			 * 载荷只表示本次被选中的节点路径；如需当前完整选择集合，请调用 {@link getSelection}。
			 */
			readonly onDidSelectNode: Event<ISelectionDeltaEvent>;

			/**
			 * 节点被取消选择时触发。
			 *
			 * 载荷只表示本次被取消选择的节点路径；如需当前完整选择集合，请调用 {@link getSelection}。
			 */
			readonly onDidDeselectNode: Event<ISelectionDeltaEvent>;

			/**
			 * 当前场景选择被清空时触发。
			 */
			readonly onDidClearSelection: Event<void>;
		}

scene.SceneRuntimeAcquisition.declaration:
export interface SceneRuntimeAcquisition {
			readonly instance: SceneInstance;

			/** 释放本次引用，不保存场景；重复调用无副作用，失败后可以重试 */
			release(): Thenable<void>;
		}

scene.SceneWebviewContribution.declaration:
export interface SceneWebviewContribution {
			/**
			 * 相对于扩展根目录的 JS 入口文件路径。
			 * 在场景 webview 中以 `<script type="module">` 加载。
			 *
			 * @example `'dist/web/index.js'`
			 */
			script: string;

			/**
			 * 相对于扩展根目录的 CSS 样式文件路径。
			 * 每个文件以 `<link rel="stylesheet">` 注入。
			 *
			 * @example `['dist/web/assets/vendor.css', 'dist/web/assets/index.css']`
			 */
			styles?: string[];
		}

scene.ISceneWebviewMessage.declaration:
export interface ISceneWebviewMessage {
			/** webview 侧发送的消息体。 */
			readonly payload: unknown;
			/** 向来源 webview 回复消息。 */
			reply(response: unknown): void;
			/**
			 * 调用来源 webview 侧通过 `registerApi` 注册的 API。
			 *
			 * 如果来源 webview 没有注册对应 `method`，调用会 reject。
			 *
			 * 不需要传参数时，可直接把 options 作为第二个参数：
			 * `msg.invoke('init', { timeout: 1000 })`。
			 */
			invoke<T = unknown>(method: string, options?: SceneWebviewContributionInvokeOptions): Promise<T | undefined>;
			invoke<T = unknown>(
				method: string,
				params: unknown,
				options?: SceneWebviewContributionInvokeOptions
			): Promise<T | undefined>;
		}

scene.SceneWebviewContributionInvokeOpti.declaration:
export interface SceneWebviewContributionInvokeOptions {
			/** 仅调用此作者场景 Runtime，并等待该贡献脚本完成加载。必须作为 invoke 的显式第三个参数传入；省略时保持广播行为。 */
			readonly runtime?: Pick<SceneRuntimeRef, 'runtimeId' | 'generation'>;
			/** 本次调用等待 webview 响应的超时时间，单位毫秒。 */
			readonly timeout?: number;
		}

scene.ISceneWebviewContributionApi.declaration:
export interface ISceneWebviewContributionApi {
			/** 发送消息到注册该贡献的扩展宿主。 */
			postMessage(message: { type: string;[key: string]: unknown }): void;

			/** 接收扩展宿主通过 `reply` 或句柄发送到当前贡献的消息。 */
			onMessage(handler: (msg: { type: string;[key: string]: unknown }) => void): Disposable;

			/** 监听底层场景 webview bridge 事件。 */
			on(event: string, handler: (data: unknown) => void): Disposable;

			/**
			 * 注册供扩展宿主调用的 webview 侧 API。
			 *
			 * 空名称会抛错；重复注册同名 API 会抛错。
			 * 释放返回的 Disposable 会注销该 API。
			 */
			registerApi(name: string, handler: (params?: unknown) => unknown | Promise<unknown>): Disposable;
		}

scene.ISceneViewControls.declaration:
export interface ISceneViewControls {
			/** 等待当前拖拽清理后切换场景维度 */
			setSceneDimension(is2D: boolean): Promise<void>;
		}

scene.ISceneWebviewContributionHandle.declaration:
export interface ISceneWebviewContributionHandle extends Disposable {
			/**
			 * 接收来自 webview 的消息。
			 */
			readonly onDidReceiveMessage: Event<ISceneWebviewMessage>;

			/**
			 * 调用当前已加载场景 webview 中该贡献通过 `registerApi` 注册的 API。
			 *
			 * 如果某个 webview 没有注册对应 `method`，调用会 reject。
			 * 返回值包含所有成功处理调用的 webview 结果；当前没有已加载 scene webview 时返回空数组。
			 *
			 * 不需要传参数时，可直接把 options 作为第二个参数：
			 * `handle.invoke('init', { timeout: 1000 })`。
			 */
			invoke<T = unknown>(method: string, options?: SceneWebviewContributionInvokeOptions): Promise<T[]>;
			invoke<T = unknown>(
				method: string,
				params: unknown,
				options?: SceneWebviewContributionInvokeOptions
			): Promise<T[]>;
		}

